app.delete('/api/habits/:id', async (req, res) => {
  const auth = await authenticateRequest(req);
  if (!auth) {
    return res.status(401).json({ message: 'Unauthorized' });
  }

  try {
    const habit = await auth.pb.collection('habits').getOne(req.params.id);

